import { redirect } from 'next/navigation'; import { requireUser } from '@/lib/auth'; import WorkspaceShell from '@/components/WorkspaceShell'; import VendorQuickCreate from '@/components/VendorQuickCreate';
export default async function Vendors(){const {supabase,user,profile}=await requireUser();if(!user||!profile)redirect('/login');const org=profile.organization_id;const [{data:vendors},{data:orders}]=await Promise.all([supabase.from('vendors').select('*').eq('organization_id',org).order('created_at',{ascending:false}),supabase.from('vendor_orders').select('vendor_id,gross_amount,commission_amount,vendor_amount,status').eq('organization_id',org)]);return <WorkspaceShell title="Vendors" subtitle="Commission commerce and supplier relationships" profile={profile}><div className="mx-auto max-w-7xl px-6 py-8"><div className="grid gap-6 lg:grid-cols-[1fr_360px]"><section><h1 className="text-3xl font-bold">Vendor network</h1><p className="mt-2 text-slate-600">Sell permitted partner products while WorkflowOS tracks your margin and what the original vendor is owed.</p><div className="mt-6 grid gap-4 md:grid-cols-2">{(vendors??[]).map((v:any)=>{const vo=(orders??[]).filter((o:any)=>o.vendor_id===v.id);const gross=vo.reduce((a:number,o:any)=>a+Number(o.gross_amount||0),0);const commission=vo.reduce((a:number,o:any)=>a+Number(o.commission_amount||0),0);return <div className="rounded-3xl border bg-white p-5 shadow-sm" key={v.id}><div className="flex justify-between gap-3"><div><div className="font-semibold">{v.name}</div><div className="text-sm text-slate-500">{v.source_url||v.contact_email||'Direct vendor'}</div></div><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-semibold">{Number(v.commission_rate||0)}%</span></div><div className="mt-5 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-slate-50 p-3"><div className="text-xs text-slate-500">Gross sales</div><div className="mt-1 font-bold">₦{gross.toLocaleString()}</div></div><div className="rounded-2xl bg-slate-50 p-3"><div className="text-xs text-slate-500">Your commission</div><div className="mt-1 font-bold">₦{commission.toLocaleString()}</div></div></div></div>})}{!vendors?.length&&<div className="rounded-3xl border border-dashed bg-white p-8 text-sm text-slate-500">No vendors yet.</div>}</div></section><VendorQuickCreate/></div></div></WorkspaceShell>}
